меню.
void MenuNext(void)
{
// на строку вниз
if (MenuTek->Mi->ni < MenuTek->ns-1){
MenuTek->Mi->ni++; // переход на следующую строку
if ((MenuTek->Mi->ni - MenuTek->Mi->nb) >= Disply.ns)
MenuTek->Mi->nb++; // скроллинг вверх
MenuDisp();
}
}
