Обработчик SimpleAPI: проверка токена и защита от replay
Сюда стекаются запросы и из PWA, и из старых Shortcuts-шаблонов. Значение объекта приходит в формате
токен:таймстемп
, скрипт разбирает его и игнорирует всё, что старше 15 секунд:
javascript
for (const gate of GATES) {
 on({ id: gate.simpleApiState, change: 'any', ack: false }, (obj) => {
 const val = String(obj.state.val || '');
 const [token, tsRaw] = val.split(':');
 const tsNum = Number(tsRaw);

 if (!token || !tsNum) return;

 const tsMs = tsNum < 1e12 ? tsNum * 1000 : tsNum;
 const ageMs = Date.now() - tsMs;

 if (ageMs < 0 || ageMs > MAX_AGE_MS) {
 log(`gates: протухший запрос (${gate.id}), возраст ${Math.round(ageMs / 1000)} сек — игнор`);
 setTimeout(() => setState(gate.simpleApiState, '', true), 500);
 return;
 }

 const user = findUserByToken(token);
 if (!user) {
 log(`gates: неизвестный токен на ${gate.id}`);
 return;
 }
 if (!hasPermission(user, gate.permission)) {
 log(`gates: нет прав ${gate.permission} — ${user.name}`);
 return;
 }

 openGate(gate, user.name);
 requestVideo(gate);
 logToBackend(gate, user.name, 'sapi');

 setTimeout(() => setState(gate.simpleApiState, '', true), 1000);
 });
}
